<script setup>
import MonthlyClassificationTab from '../components/MonthlyClassificationTab.vue'
import ArticleCodeClassificationTab from '../components/ArticleCodeClassificationTab.vue'
import ClassificationPricesTab from '../components/ClassificationPricesTab.vue'
import {articleCategories} from '../constants/articleCategories.js'
import ClientSalesLinesModal from '../components/ClientSalesLinesModal.vue'
const salesDetail=ref(null),loadedSalesFilters=ref(null)
const categoryListName=categories=>categories.length?categories.map(categoryName).join(', '):'Cap classificació marcada'
function openSalesDetail(row,year,centre,category){const filters=loadedSalesFilters.value||{from:from.value,to:to.value,article:article.value},hasCategoryFilter=arguments.length>=4,categories=hasCategoryFilter?(Array.isArray(category)?category:[category]):undefined;const start=`${year}-01-01`,end=`${year}-12-31`;salesDetail.value={clientCode:row.clientCode,clientName:row.clientName,year,from:filters.from>start?filters.from:start,to:filters.to<end?filters.to:end,article:filters.article,isCentre:centre!==undefined,centreName:centre?.centreName,hasCategoryFilter,categories,category:hasCategoryFilter&&!Array.isArray(category)?category:undefined,categoryName:hasCategoryFilter?(categories.length===1?categoryName(categories[0]):categoryListName(categories)):''}}
const selectedCategoriesForTotal=yearTotal=>visibleCategoryTotals(yearTotal).map(item=>item.category)
function openVisibleSalesDetail(row,year,centre){if(salesClassificationMode.value!=='selected')return openSalesDetail(row,year,centre);const yearTotal=(centre?.years||row.years)[year],categories=selectedCategoriesForTotal(yearTotal);if(!categories.length)return;openSalesDetail(row,year,centre,categories)}
import CentreRating from '../components/CentreRating.vue'
import{ref,onMounted,computed}from'vue';import{useRoute}from'vue-router';import{api}from'../services/api.js';import{can,canRateCentres}from'../stores/auth.js';import UiState from'../components/UiState.vue';import BaseModal from'../components/BaseModal.vue';import ConfirmDialog from'../components/ConfirmDialog.vue';import ArticleSalesTab from'../components/ArticleSalesTab.vue';import CompostGroupingTab from'../components/CompostGroupingTab.vue'
const expandedClients=ref(new Set())
const clientSearch=ref(String(useRoute().query.clientSearch||'')),deliveryNoteSearch=ref(''),deliveryNoteSearchError=ref('')
const normalizeSearch=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('ca').trim()
const categoryKey=value=>value??'__none__'
const categoryName=value=>value==null?'Sense classificar':articleCategories.find(([key])=>key===value)?.[1]||value
const categoryOrder=value=>{if(value==null)return articleCategories.length;const index=articleCategories.findIndex(([key])=>key===value);return index<0?articleCategories.length+1:index}
const categoryTotals=yearTotal=>{const totals=Array.isArray(yearTotal?.categories)?yearTotal.categories:Object.values(yearTotal?.categories||{});return totals.filter(item=>Number(item.quantity||0)||Number(item.totalAmount||0)).sort((a,b)=>categoryOrder(a.category)-categoryOrder(b.category)||categoryName(a.category).localeCompare(categoryName(b.category),'ca'))}
const salesClassificationMode=ref('all')
const allSelectableCategoryKeys=[...articleCategories.map(([key])=>key),'__none__']
const selectedCategoryKeys=ref([...allSelectableCategoryKeys])
const visibleCategoryTotals=yearTotal=>categoryTotals(yearTotal).filter(item=>salesClassificationMode.value==='all'||selectedCategoryKeys.value.includes(categoryKey(item.category)))
const hasVisibleCategoryTotals=yearTotal=>salesClassificationMode.value==='all'?!!yearTotal:visibleCategoryTotals(yearTotal).length>0
const visibleYearTotal=yearTotal=>salesClassificationMode.value==='all'?yearTotal:visibleCategoryTotals(yearTotal).reduce((sum,item)=>({quantity:sum.quantity+Number(item.quantity||0),totalAmount:sum.totalAmount+Number(item.totalAmount||0)}),{quantity:0,totalAmount:0})
const rowClientMatchesSearch=(row,term)=>normalizeSearch(row.clientName).includes(term)||normalizeSearch(row.clientCode).includes(term)
const centreMatchesSearch=(centre,term)=>normalizeSearch(centre.centreName).includes(term)
const rowMatchesCentreSearch=row=>{const term=normalizeSearch(clientSearch.value);return !!term&&!rowClientMatchesSearch(row,term)&&(row.centres||[]).some(centre=>centreMatchesSearch(centre,term))}
const searchedClients=computed(()=>{const term=normalizeSearch(clientSearch.value);return sales.value.rows.filter(row=>!term||rowClientMatchesSearch(row,term)||(row.centres||[]).some(centre=>centreMatchesSearch(centre,term)))})
const centreHasVisibleCategories=centre=>salesClassificationMode.value==='all'||Object.values(centre.years||{}).some(yearTotal=>visibleCategoryTotals(yearTotal).length)
const rowHasVisibleCategories=row=>salesClassificationMode.value==='all'||Object.values(row.years||{}).some(yearTotal=>visibleCategoryTotals(yearTotal).length)||(row.centres||[]).some(centreHasVisibleCategories)
const classificationChoices=computed(()=>{const seen=new Set();const add=yearTotal=>categoryTotals(yearTotal).forEach(item=>seen.add(categoryKey(item.category)));for(const row of searchedClients.value){Object.values(row.years||{}).forEach(add);for(const centre of row.centres||[])Object.values(centre.years||{}).forEach(add)}return [...articleCategories.map(([key,label])=>({key,label})),{key:'__none__',label:'Sense classificar'}].filter(item=>seen.has(item.key))})
function selectAllSalesClassifications(){selectedCategoryKeys.value=classificationChoices.value.map(item=>item.key)}
function clearSalesClassifications(){selectedCategoryKeys.value=[]}
const latestYear=computed(()=>sales.value.years.length?Math.max(...sales.value.years.map(Number)):null)
const byLatestTonnes=(a,b)=>Number(b.years[latestYear.value]?.quantity||0)-Number(a.years[latestYear.value]?.quantity||0)||(a.clientName||a.centreName||'').localeCompare(b.clientName||b.centreName||'','ca')
const visibleCentres=row=>{const term=normalizeSearch(clientSearch.value),showAllCentres=!term||rowClientMatchesSearch(row,term);return [...(row.centres||[])].filter(centre=>centreHasVisibleCategories(centre)&&(showAllCentres||centreMatchesSearch(centre,term))).sort(byLatestTonnes)}
const sortedCentres=visibleCentres
const visibleClients=computed(()=>searchedClients.value.filter(rowHasVisibleCategories).sort(byLatestTonnes))
const isClientExpanded=row=>expandedClients.value.has(row.clientCode)||rowMatchesCentreSearch(row)
function toggleCentres(code){if(expandedClients.value.has(code))expandedClients.value.delete(code);else expandedClients.value.add(code)}
function openDeliveryNoteSearch(){const note=deliveryNoteSearch.value.trim();deliveryNoteSearchError.value='';if(!note){deliveryNoteSearchError.value='Indica un número d’albarà';return}salesDetail.value={noteNumber:note,clientName:`Albarà ${note}`,year:'',from:from.value,to:to.value,article:article.value}}
const route=useRoute(),validTabs=new Set(['sales','articles','monthly-classification','compost','code-classification','classification-prices','imports']),today=new Date().toISOString().slice(0,10),defaultFrom=`${new Date().getFullYear()-6}-01-01`;const tab=ref(validTabs.has(String(route.query.tab||''))?String(route.query.tab):'sales'),from=ref(String(route.query.from||defaultFrom)),to=ref(String(route.query.to||today)),article=ref(String(route.query.article||'')),sales=ref({years:[],rows:[]}),imports=ref([]),selected=ref(null),loading=ref(false),processing=ref(false),error=ref(''),notice=ref(''),file=ref(null),dragging=ref(false),editOpen=ref(false),editing=ref(null),confirmOpen=ref(false),confirmError=ref(''),onlyIssues=ref(false),clientFilter=ref(''),noteFilter=ref('')
const money=value=>new Intl.NumberFormat('ca-ES',{style:'currency',currency:'EUR'}).format(Number(value||0)),quantity=value=>new Intl.NumberFormat('ca-ES',{maximumFractionDigits:4}).format(Number(value||0)),json=value=>Array.isArray(value)?value:(value?JSON.parse(value):[])
const filteredRows=computed(()=>selected.value?.rows?.filter(r=>(!onlyIssues.value||json(r.warnings).length)&&(!clientFilter.value||r.client_name?.toLowerCase().includes(clientFilter.value.toLowerCase()))&&(!noteFilter.value||r.delivery_note_number?.toLowerCase().includes(noteFilter.value.toLowerCase())))||[])
const comparisonLabels={new:'Nou albarà',unchanged:'Igual: s’omet',replace:'Substituir albarà sencer'}
async function loadSales(){loading.value=true;error.value='';const filters={from:from.value,to:to.value,article:article.value};try{sales.value=await api.get(`/sales/clients?from=${filters.from}&to=${filters.to}&article=${encodeURIComponent(filters.article)}`);loadedSalesFilters.value=filters}catch(e){error.value=e.message}finally{loading.value=false}}
async function loadImports(reportError=true){try{imports.value=await api.get('/imports');return true}catch(e){if(reportError)error.value=e.message;return false}}
function choose(event){const chosen=event.target.files?.[0]||event.dataTransfer?.files?.[0];dragging.value=false;if(chosen)file.value=chosen;if(event.target?.type==='file')event.target.value=''}
async function upload(){if(!file.value)return;processing.value=true;error.value='';notice.value='';try{const data=new FormData();data.append('file',file.value);selected.value=await api.post('/imports/delivery-notes/preview',data);tab.value='preview';notice.value='PDF comparat amb els albarans existents. Reviseu el resum abans de confirmar.';file.value=null;await loadImports(false)}catch(e){error.value=e.message}finally{processing.value=false}}
async function openImport(id){loading.value=true;try{selected.value=await api.get('/imports/'+id);tab.value='preview'}catch(e){error.value=e.message}finally{loading.value=false}}
function edit(row){editing.value={id:row.id,deliveryNoteNumber:row.delivery_note_number,date:row.delivery_date?.slice(0,10),productCode:row.product_code,concept:row.concept,quantity:row.quantity,unitPrice:row.unit_price,taxableBase:row.taxable_base,vatAmount:row.vat_amount,totalAmount:row.total_amount,vehiclePlate:row.vehicle_plate||'',trailerPlate:row.trailer_plate||''};editOpen.value=true}
async function saveRow(){selected.value=await api.patch(`/imports/${selected.value.id}/rows/${editing.value.id}`,editing.value);editOpen.value=false}
function openConfirm(){confirmError.value='';confirmOpen.value=true}
async function confirmImport(){if(processing.value)return;processing.value=true;confirmError.value='';error.value='';try{selected.value=await api.post(`/imports/${selected.value.id}/confirm`,{});confirmOpen.value=false;notice.value=`Importació completada: ${selected.value.confirmed_row_count} línies incorporades, ${selected.value.discarded_row_count} línies d’albarans iguals omeses i ${selected.value.replaced_row_count||0} línies anteriors substituïdes.`;await Promise.all([loadImports(false),loadSales()])}catch(e){confirmError.value=e.message}finally{processing.value=false}}
onMounted(()=>Promise.all([loadSales(),loadImports()]))
</script>
<template>
 <div class="tabs" role="tablist"><button :class="{active:tab==='sales'}" @click="tab='sales'">Vendes per client</button><button :class="{active:tab==='articles'}" @click="tab='articles'">Vendes per articles</button><button :class="{active:tab==='monthly-classification'}" @click="tab='monthly-classification'">Vendes per mesos</button><button :class="{active:tab==='compost'}" @click="tab='compost'">Classificació articles</button><button :class="{active:tab==='code-classification'}" @click="tab='code-classification'">Classificació per codi</button><button :class="{active:tab==='classification-prices'}" @click="tab='classification-prices'">Preus per classificació</button><button :class="{active:tab==='imports'}" @click="tab='imports'">Importacions</button><button v-if="selected" :class="{active:tab==='preview'}" @click="tab='preview'">Revisió #{{selected.id}}</button></div>
 <div v-if="error" class="alert error" role="alert">{{error}}</div>
 <div v-if="notice" class="alert success" role="status">{{notice}}</div>
 <section v-if="tab==='sales'">
  <form class="card filters sales-filters" @submit.prevent="loadSales"><label>Des de<input v-model="from" type="date" required></label><label>Fins a<input v-model="to" type="date" required></label><label class="client-search">Client<input v-model="clientSearch" type="search" placeholder="Client, codi o centre"></label><label class="article-search">Article<input v-model="article" type="search" placeholder="Codi o nom de l’article"></label><label class="delivery-note-search">Albarà<input v-model="deliveryNoteSearch" type="search" placeholder="Codi" @keydown.enter.prevent="openDeliveryNoteSearch"></label><button type="button" class="button secondary delivery-note-button" @click="openDeliveryNoteSearch">Veure</button><button class="button primary">Consultar</button></form><p v-if="deliveryNoteSearchError" class="delivery-note-error">{{deliveryNoteSearchError}}</p>
  <div class="tabs sales-subtabs" role="tablist" aria-label="Apartats de vendes per client"><button type="button" :class="{active:salesClassificationMode==='all'}" @click="salesClassificationMode='all'">Totes les classificacions</button><button type="button" :class="{active:salesClassificationMode==='selected'}" @click="salesClassificationMode='selected'">Classificacions marcades</button></div>
  <section v-if="salesClassificationMode==='selected'" class="card classification-filter-card"><header class="classification-filter-head"><strong>Classificacions visibles</strong><div><button type="button" class="button secondary compact" @click="selectAllSalesClassifications">Totes</button><button type="button" class="button secondary compact" @click="clearSalesClassifications">Netejar</button></div></header><div class="classification-picker"><label v-for="item in classificationChoices" :key="item.key" class="classification-check"><input v-model="selectedCategoryKeys" type="checkbox" :value="item.key"><span>{{item.label}}</span></label></div></section>
  <UiState :loading="loading" :empty="!visibleClients.length" :empty-text="clientSearch.trim()?'No s’ha trobat cap client amb aquesta cerca i els filtres actuals.':'No hi ha vendes confirmades amb aquests filtres.'"><div class="table-wrap"><table class="client-sales-matrix"><thead><tr><th>Nom del client</th><th v-for="year in sales.years" :key="year">{{year}}</th></tr></thead><tbody><template v-for="row in visibleClients" :key="row.clientCode"><tr><td data-label="Client"><RouterLink class="client-matrix-link" :to="{name:'client-sales-detail',params:{clientCode:row.clientCode},query:{from,to,article,clientSearch}}"><strong>{{row.clientName}}</strong><small>{{row.clientCode}}</small></RouterLink><button class="button secondary compact centre-toggle" :aria-expanded="isClientExpanded(row)" :aria-label="`Centres de ${row.clientName}`" @click="toggleCentres(row.clientCode)">{{isClientExpanded(row)?'▾':'▸'}} {{visibleCentres(row).length}} centres</button></td><td v-for="year in sales.years" :key="year" :data-label="String(year)"><div v-if="row.years[year]&&hasVisibleCategoryTotals(row.years[year])" class="client-year-cell"><button type="button" class="tonnes-detail total-detail" :aria-label="'Veure linies de '+row.clientName+' de '+year" @click="openVisibleSalesDetail(row,year)">{{quantity(visibleYearTotal(row.years[year]).quantity)}} t</button><span>{{money(visibleYearTotal(row.years[year]).totalAmount)}}</span><div v-if="visibleCategoryTotals(row.years[year]).length" class="classification-breakdown"><button v-for="item in visibleCategoryTotals(row.years[year])" :key="categoryKey(item.category)" type="button" class="classification-detail" :aria-label="'Veure productes de '+row.clientName+' de '+year+' per '+categoryName(item.category)" @click="openSalesDetail(row,year,undefined,item.category)"><span>{{categoryName(item.category)}}</span><strong>{{quantity(item.quantity)}} t</strong></button></div></div><span v-else>—</span></td></tr><template v-if="isClientExpanded(row)"><tr v-for="centre in visibleCentres(row)" :key="centre.centreName" class="centre-row"><td data-label="Centre de procedència">{{centre.centreName||'Sense centre informat'}}<CentreRating v-if="centre.centreName" :client-code="row.clientCode" :centre-name="centre.centreName" :rating="centre.rating" :comment="centre.comment" :editable="canRateCentres()" @saved="centre.rating=$event" @comment-saved="centre.comment=$event"/></td><td v-for="year in sales.years" :key="year" :data-label="String(year)"><div v-if="centre.years[year]&&hasVisibleCategoryTotals(centre.years[year])" class="client-year-cell"><span class="rated-value"><button type="button" class="tonnes-detail total-detail" :aria-label="'Veure linies de '+(centre.centreName||'Sense centre informat')+' de '+year" @click="openVisibleSalesDetail(row,year,centre)">{{quantity(visibleYearTotal(centre.years[year]).quantity)}} t</button><i v-if="centre.rating" class="rating-dot" :style="{backgroundColor:`hsl(${(centre.rating-1)*30} 70% 45%)`}" role="img" :aria-label="`Valoració ${centre.rating} de 5`" :title="`Valoració ${centre.rating} de 5`"></i></span><span>{{money(visibleYearTotal(centre.years[year]).totalAmount)}}</span><div v-if="visibleCategoryTotals(centre.years[year]).length" class="classification-breakdown"><button v-for="item in visibleCategoryTotals(centre.years[year])" :key="categoryKey(item.category)" type="button" class="classification-detail" :aria-label="'Veure productes de '+(centre.centreName||'Sense centre informat')+' de '+year+' per '+categoryName(item.category)" @click="openSalesDetail(row,year,centre,item.category)"><span>{{categoryName(item.category)}}</span><strong>{{quantity(item.quantity)}} t</strong></button></div></div><span v-else>—</span></td></tr></template></template></tbody></table></div></UiState>
 </section>
 <ArticleSalesTab v-else-if="tab==='articles'"/>
 <MonthlyClassificationTab v-else-if="tab==='monthly-classification'"/>
 <ClassificationPricesTab v-else-if="tab==='classification-prices'"/>
 <CompostGroupingTab v-else-if="tab==='compost'"/>
 <ArticleCodeClassificationTab v-else-if="tab==='code-classification'"/>
 <section v-else-if="tab==='imports'">
  <div v-if="can('sales_clients.manage')" class="card upload-card"><label class="drop-zone" :class="{dragging}" @dragover.prevent="dragging=true" @dragleave="dragging=false" @drop.prevent="choose"><input class="sr-only" type="file" accept="application/pdf,.pdf" @change="choose"><span class="empty-icon">⇧</span><strong>{{file?.name||'Arrossegueu un PDF o feu clic per seleccionar-lo'}}</strong><small>PDF amb capa de text i albarans complets</small></label><button class="button primary" :disabled="!file||processing" @click="upload">{{processing?'Comparant totes les pàgines…':'Previsualitzar importació'}}</button><p class="import-mode-help">Els albarans repetits i iguals s’ometen. Si hi ha qualsevol diferència, se substitueix l’albarà sencer en confirmar. Els nous s’afegeixen. Es comparen per client, número i any; utilitzeu un PDF amb els albarans complets.</p></div>
  <UiState :empty="!imports.length" empty-text="Encara no hi ha importacions."><div class="table-wrap"><table><thead><tr><th>Fitxer</th><th>Tipus</th><th>Data</th><th>Estat</th><th>Clients</th><th>Línies</th><th>Total</th><th></th></tr></thead><tbody><tr v-for="item in imports" :key="item.id"><td data-label="Fitxer">{{item.original_filename}}</td><td data-label="Tipus">{{item.import_mode==='overwrite'?'Sobreescriptura':'Importació'}}</td><td data-label="Data">{{new Date(item.created_at).toLocaleString('ca-ES')}}</td><td data-label="Estat"><span class="badge" :class="item.status==='completed'?'success':'neutral'">{{item.status}}</span></td><td data-label="Clients">{{item.client_count}}</td><td data-label="Línies">{{item.row_count}}</td><td data-label="Total">{{money(item.total_amount)}}</td><td><button class="button secondary compact" @click="openImport(item.id)">Consultar</button></td></tr></tbody></table></div></UiState>
 </section>
 <section v-else-if="selected" class="preview">
  <div v-if="selected.status==='pending_review'" class="alert warning" role="status"><strong>Comparació d’albarans complets.</strong> Els iguals es conservaran. Qualsevol canvi substituirà totes les línies de l’albarà en confirmar. Els albarans que no apareixen al PDF es conservaran.</div>
  <div v-if="selected.comparison_error" class="alert error" role="alert">{{selected.comparison_error}}</div>
  <div v-if="selected.comparison" class="summary-grid" aria-label="Comparació d’albarans"><article class="card"><small>Albarans nous</small><strong>{{selected.comparison.newNotes}}</strong></article><article class="card"><small>Albarans iguals: s’ometen</small><strong>{{selected.comparison.unchangedNotes}}</strong></article><article class="card"><small>Albarans diferents: se substitueixen</small><strong>{{selected.comparison.replacedNotes}}</strong></article></div>
  <div class="summary-grid"><article class="card"><small>Empresa</small><strong>{{selected.detected_company}}</strong></article><article class="card"><small>Pàgines</small><strong>{{selected.page_count}}</strong></article><article class="card"><small>Clients</small><strong>{{selected.client_count}}</strong></article><article class="card"><small>Línies</small><strong>{{selected.row_count}}</strong></article><article v-if="selected.status==='completed'" class="card"><small>Confirmades</small><strong>{{selected.confirmed_row_count}}</strong></article><article v-if="selected.status==='completed'" class="card"><small>Línies iguals omeses</small><strong>{{selected.discarded_row_count}}</strong></article><article v-if="selected.status==='completed'&&selected.updated_row_count" class="card"><small>Preus actualitzats</small><strong>{{selected.updated_row_count||0}}</strong></article><article v-if="selected.status==='completed'" class="card"><small>Línies anteriors substituïdes</small><strong>{{selected.replaced_row_count||0}}</strong></article><article class="card"><small>Base</small><strong>{{money(selected.taxable_base_total)}}</strong></article><article class="card"><small>IVA</small><strong>{{money(selected.vat_total)}}</strong></article><article class="card"><small>Total</small><strong>{{money(selected.total_amount)}}</strong></article><article class="card"><small>Incidències</small><strong>{{json(selected.warnings).length}}</strong></article></div>
  <details v-if="json(selected.warnings).length" class="alert warning import-issues" open>
   <summary><strong>Cal revisar aquestes incidències:</strong><span>{{json(selected.warnings).length}}</span></summary>
   <ul><li v-for="warning in json(selected.warnings)">{{warning.message||warning}}</li></ul>
  </details>
  <div class="toolbar preview-tools"><div class="search"><input v-model="clientFilter" placeholder="Filtrar client"><input v-model="noteFilter" placeholder="Filtrar albarà"></div><label class="check"><input v-model="onlyIssues" type="checkbox"> Només incidències</label><button v-if="selected.status==='pending_review'&&can('sales_clients.manage')" class="button primary" @click="openConfirm" :disabled="!!selected.comparison_error">Confirmar importació</button></div>
  <div class="table-wrap"><table class="preview-table"><thead><tr><th>Pàg.</th><th>Client</th><th>Albarà/data</th><th>Producte/concepte</th><th>Quantitat × preu</th><th>Base + IVA</th><th>Total</th><th>Revisió</th></tr></thead><tbody><tr v-for="row in filteredRows" :key="row.id" :class="{issue:json(row.warnings).length}"><td data-label="Pàgina">{{row.source_page}}</td><td data-label="Client">{{row.client_name}}<small>{{row.client_code}}</small><small v-if="row.centre_name">Centre: {{row.centre_name}}</small></td><td data-label="Albarà"><strong>{{row.delivery_note_number}}</strong><small>{{row.delivery_date?.slice(0,10)}}</small></td><td data-label="Producte">{{row.product_code}} — {{row.concept}}<small v-if="row.waste_code">LER {{row.waste_code}}</small></td><td data-label="Quantitat">{{row.quantity}} × {{row.unit_price}}</td><td data-label="Base">{{money(row.taxable_base)}} + {{row.vat_amount==null?'IVA no informat':money(row.vat_amount)}}</td><td data-label="Total">{{money(row.total_amount)}}</td><td><span v-if="row.comparison_action&&selected.status==='pending_review'" class="badge neutral">{{comparisonLabels[row.comparison_action]}}</span><div v-for="warning in json(row.warnings)" class="warning-text">{{warning}}</div><button v-if="selected.status==='pending_review'&&can('sales_clients.manage')" class="button secondary compact" @click="edit(row)">Editar</button></td></tr></tbody></table></div>
 </section>
 <BaseModal :open="editOpen" title="Corregir línia" @close="editOpen=false"><form v-if="editing" id="row-form" class="form-grid" @submit.prevent="saveRow"><label>Albarà<input v-model="editing.deliveryNoteNumber" required></label><label>Data<input v-model="editing.date" type="date"></label><label>Producte<input v-model="editing.productCode"></label><label>Quantitat<input v-model="editing.quantity" inputmode="decimal"></label><label class="full">Concepte<textarea v-model="editing.concept"></textarea></label><label>Preu unitari<input v-model="editing.unitPrice" inputmode="decimal"></label><label>Base imposable<input v-model="editing.taxableBase" inputmode="decimal"></label><label>IVA<input v-model="editing.vatAmount" inputmode="decimal"></label><label>Total<input v-model="editing.totalAmount" inputmode="decimal"></label><label>Matrícula<input v-model="editing.vehiclePlate"></label><label>Remolc<input v-model="editing.trailerPlate"></label></form><template #actions><button class="button secondary" @click="editOpen=false">Cancel·lar</button><button form="row-form" class="button primary">Desar correcció</button></template></BaseModal>
 <ClientSalesLinesModal :selection="salesDetail" @close="salesDetail=null"/>
 <ConfirmDialog :open="confirmOpen" title="Confirmar importació" message="Els albarans iguals s’ometran i els diferents se substituiran sencers pels del PDF. Els albarans nous s’afegiran i els que no surten al PDF es conservaran. Aquesta acció quedarà auditada." :busy="processing" :error="confirmError" busy-text="Confirmant importació…" @cancel="confirmOpen=false" @confirm="confirmImport"/>
